import{_ as a,o as n,c as s,a2 as t}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"DSH 深度拆解","text":"DeepSeek Harness 源码级学习资料","tagline":"从 Cordis 插件框架到 Agent Loop 状态机 —— 一份面向 Agent 开发岗位的完整拆解","actions":[{"theme":"brand","text":"开始学习","link":"/guide/why-dsh"},{"theme":"alt","text":"核心概念速览","link":"/guide/concepts"},{"theme":"alt","text":"面试题库","link":"/interview/qa"}]},"features":[{"icon":"🧩","title":"一切皆插件","details":"DSH 建立在 vendored Cordis 之上：模型适配器、工具注册表、会话日志，甚至 Agent Loop 本身都是插件，可被配置替换。"},{"icon":"📜","title":"事件溯源式会话日志","details":"追加式 SessionEvent 日志是唯一真源。模型可见即已记录，回放、fork、恢复、遥测全部派生自同一事件流。"},{"icon":"🔁","title":"Turn / Step 状态机","details":"轮次排空 inbox，步骤是一次模型请求 + 工具执行。waterfall 事件让策略监听器在不动循环代码的前提下拦截一切。"},{"icon":"🛠️","title":"能力 Seam 架构","details":"Service Definition / Provider / Consumer 三角色。替换一个提供方（如把 bash 指向远程沙箱），产品整体行为随之改变。"},{"icon":"🌊","title":"流式端到端","details":"provider 流 → llm/stream waterfall → assistant/chunk 持久事件 → Web GUI 增量渲染。每个环节都可拦截、可回放。"},{"icon":"🏗️","title":"多代理编排","details":"subagent 能力 seam、受限 JS workflow 引擎、后台 jobs、持久 goal 循环、Ralph 全新代理迭代——全部是工具，不是特权内核。"}],"footer":"MIT Licensed · 基于 deepseek-harness 0.1.0-rc.5 源码"},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),i={name:"index.md"};function r(o,e,l,p,d,c){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h2 id="这份资料是什么" tabindex="-1">这份资料是什么 <a class="header-anchor" href="#这份资料是什么" aria-label="Permalink to &quot;这份资料是什么&quot;">​</a></h2><p>这是对 <a href="https://github.com/deepseek-ai/DeepSeek-Harness" target="_blank" rel="noreferrer">DeepSeek Harness（DSH）</a> 的一次<strong>源码级深度拆解</strong>。DSH 是一个生产级 Agent Harness：插件化架构、事件溯源会话日志、完整的工具执行管道、多代理编排系统、Web GUI。它同时是我（本资料作者）研究 agent 系统的第一个深度案例。</p><p>资料分四条主线：</p><ul><li><strong><a href="/guide/why-dsh">导读</a></strong>：为什么要研究这个项目，核心概念与术语，架构总览</li><li><strong><a href="/deep-dive/agent-loop">深度拆解</a></strong>：8 篇文章，逐子系统拆解核心循环、工具管道、沙箱、上下文工程、编排、LLM 层、Web GUI、持久化与工程化</li><li><strong><a href="/interview/patterns">面试冲刺</a></strong>：可迁移的设计模式手册 + 高频面试题</li><li><strong><a href="/practice/extend">实战</a></strong>：跟着 cookbook 亲手给 DSH 加一个工具</li></ul><h2 id="学习路线建议" tabindex="-1">学习路线建议 <a class="header-anchor" href="#学习路线建议" aria-label="Permalink to &quot;学习路线建议&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 天：导读 3 篇 —— 建立心智模型（Cordis、事件、seam）</span></span>
<span class="line"><span>第 2 天：核心循环 + 工具系统 —— 理解 Agent 的&quot;心跳&quot;</span></span>
<span class="line"><span>第 3 天：上下文工程 + 多代理编排 —— 理解 agent 的&quot;记忆&quot;与&quot;协作&quot;</span></span>
<span class="line"><span>第 4 天：LLM 层 + Web GUI —— 理解数据如何流动</span></span>
<span class="line"><span>第 5 天：面试冲刺 + 实战扩展 —— 输出自己的理解</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>每篇拆解文章都包含：概念地图 → 模块与文件地图 → 关键类型定义 → 执行流程 → 设计权衡 → 面试要点。</p><h2 id="核心结论预览" tabindex="-1">核心结论预览 <a class="header-anchor" href="#核心结论预览" aria-label="Permalink to &quot;核心结论预览&quot;">​</a></h2><blockquote><p>DSH 的设计哲学可以浓缩为一句话：<strong>用事件流和可逆副作用取代硬编码的控制流</strong>。 循环本身没有特权——策略（审批、沙箱、压缩、遥测）以监听器身份挂在事件上， 能力（LLM、bash、文件系统、子代理）以提供方身份挂在服务 seam 上。 换掉一个插件，产品就换了一种行为；而会话日志保证每一步都可回放、可审计。</p></blockquote><p><small>说明：本文档为学习笔记，大量内容整理自 DSH 官方文档与源码；源码路径以 <code>packages/...</code> 形式给出，对应仓库根目录。关联项目：<a href="https://github.com/Bin-hy/dsh" target="_blank" rel="noreferrer">github.com/Bin-hy/dsh</a></small></p>`,10)])])}const b=a(i,[["render",r]]);export{u as __pageData,b as default};
